#!/usr/bin/env python3
from pathlib import Path
import re,json
ROOT=Path(__file__).resolve().parent
EDITS=json.loads("{\"te/index.html\":{\"మీ డేటాను స్థిరంగా ఉంచండి\":\"డేటాను శాశ్వత స్టోరేజ్‌లో నిల్వ చేయండి\",\"సురక్షిత ముగింపు బిందువును కనెక్ట్ చేయండి\":\"సురక్షిత ఎండ్‌పాయింట్‌ను కనెక్ట్ చేయండి\",\"షెడ్యూల్ నిర్వహణ\":\"నియమిత నిర్వహణకు షెడ్యూల్ సిద్ధం చేయండి\",\"నెమ్మదిగా పరివర్తన కోసం\":\"నెమ్మదిగా జరిగే డేటా రూపాంతరాల కోసం\",\"అతివ్యాప్తి చెందుతున్న పేలుళ్ల కోసం\":\"ఒకేసారి అధిక లోడ్ వచ్చే సందర్భాల్లో\",\"మీరు n8n స్వీయ-హోస్ట్ చేసినప్పుడు మీరు దేనికి చెల్లిస్తారు\":\"n8nను స్వయంగా హోస్ట్ చేస్తే ఏ ఖర్చులు ఉంటాయి?\",\"మీ n8n VPS నెల వాస్తవానికి ఎంత ఖర్చవుతుందో అంచనా వేయండి\":\"n8n VPS నెలవారీ వాస్తవ ఖర్చును అంచనా వేయండి\",\"సిఫార్సుల వెనుక వనరులు\":\"సిఫార్సులకు ఉపయోగించిన ఆధారాలు\",\"n8n కి VPS సరైన ఎంపిక అయినప్పుడు\":\"n8n కోసం VPS ఎప్పుడు సరైన ఎంపిక?\",\"మీ కాన్ఫిగరేషన్‌ను VPS ఆర్డర్‌గా మార్చండి\":\"ఎంచుకున్న కాన్ఫిగరేషన్‌తో VPS ఆర్డర్ చేయండి\"},\"te/best-vps-for-n8n.html\":{\"మంచి n8n VPS ని చెడు ఫిట్ నుండి వేరు చేసే ప్రమాణాలు\":\"n8nకు సరిపోయే VPSను గుర్తించడానికి ముఖ్యమైన ప్రమాణాలు\",\"మద్దతు సరిహద్దు\":\"సపోర్ట్ పరిధి\",\"ప్రాంతం మరియు జాప్యం\":\"సర్వర్ ప్రాంతం, లేటెన్సీ\",\"పునరుద్ధరణ మరియు అదనపు\":\"రిన్యువల్ ధరలు, అదనపు ఖర్చులు\",\"ఒక ప్రొవైడర్ నటించకుండా చిన్న సిఫార్సులు ప్రతిదానిని గెలుస్తాయి\":\"అన్ని అవసరాలకూ ఒకే ప్రొవైడర్ ఉత్తమం కాదు: సంక్షిప్త సూచనలు\",\"నాకు అతి తక్కువ రాపిడి ప్రారంభం కావాలి\":\"నాకు సులభంగా ప్రారంభించగల ఎంపిక కావాలి\",\"నేను తర్వాత క్యూ మోడ్‌ని ఆశిస్తున్నాను\":\"తర్వాత Queue Mode ఉపయోగించాలనుకుంటున్నాను\",\"వలస మరియు పోర్టబిలిటీ\":\"మైగ్రేషన్, పోర్టబిలిటీ\"},\"te/n8n-backup-restore.html\":{\"నిరంతర ఫైల్‌లు\":\"శాశ్వతంగా నిల్వ చేసే ఫైళ్లు\",\"విస్తరణ కాన్ఫిగరేషన్\":\"డిప్లాయ్‌మెంట్ కాన్ఫిగరేషన్\",\"పూర్తి ఉదాహరణ రికవరీ\":\"మొత్తం n8n ఇన్‌స్టాన్స్ పునరుద్ధరణ\",\"లాజికల్ ఎగుమతి vs పూర్తి విపత్తు పునరుద్ధరణ\":\"డేటా ఎక్స్‌పోర్ట్ vs విపత్తు తర్వాత పూర్తి పునరుద్ధరణ\",\"డేటాబేస్ను స్థిరంగా బ్యాకప్ చేయండి\":\"డేటాబేస్‌కు సుసంగతమైన బ్యాకప్ తీసుకోండి\"},\"te/install-n8n-vps-docker.html\":{\"Docker కంపోజ్ చేయండి\":\"Docker Compose\",\"2. పర్యావరణ విలువలను సృష్టించండి మరియు కీని సంరక్షించండి\":\"2. ఎన్విరాన్‌మెంట్ విలువలను సెట్ చేసి కీని భద్రపరచండి\",\"PostgreSQL ఆధారాలు\":\"PostgreSQL క్రెడెన్షియల్స్\",\"n8n మరియు PostgreSQL విడివిడిగా కొనసాగించండి\":\"n8n, PostgreSQL డేటాను విడివిడిగా శాశ్వతంగా నిల్వ చేయండి\",\"పట్టుదల లేదు\":\"శాశ్వత డేటా నిల్వ లేదు\",\"ఎన్‌క్రిప్షన్ కీని కోల్పోయింది\":\"ఎన్‌క్రిప్షన్ కీ కోల్పోవడం\"},\"te/n8n-cloud-vs-self-hosted.html\":{\"సర్వర్ ధర ద్వారా మాత్రమే కాకుండా బాధ్యతతో ఎంచుకోండి\":\"సర్వర్ ధరతో పాటు నిర్వహణ బాధ్యతను కూడా పరిగణించండి\",\"ఎప్పుడు n8n క్లౌడ్‌ని ఎంచుకోండి\":\"n8n Cloud ఎప్పుడు ఎంచుకోవాలి?\",\"ఎప్పుడు స్వీయ-హోస్ట్ VPS ని ఎంచుకోండి\":\"Self-Hosted VPS ఎప్పుడు ఎంచుకోవాలి?\",\"ఏదైనా ఉత్పత్తికి సిద్ధంగా ఉండవచ్చు\":\"రెండూ ప్రొడక్షన్‌కి సరిపోవచ్చు\",\"మీరు స్వీయ-హోస్ట్ చేసినప్పుడు మీరు ఏమి తీసుకుంటారు\":\"స్వయంగా హోస్ట్ చేస్తే ఏ బాధ్యతలు తీసుకుంటారు?\",\"ఇన్వెంటరీ మీ విస్తరణ\":\"మీ ప్రస్తుత డిప్లాయ్‌మెంట్ వివరాలను నమోదు చేయండి\",\"డేటా నివాసం\":\"డేటా నిల్వ ప్రాంతం\"},\"te/n8n-vps-requirements.html\":{\"వాస్తవానికి సర్వర్ వనరులను వినియోగిస్తుంది\":\"సర్వర్ వనరులను ఏ పనులు వినియోగిస్తాయి?\",\"1 GB ఎంట్రీని ఎలా ఉపయోగించాలి VPS\":\"ప్రారంభ స్థాయి 1 GB VPSను ఎలా ఉపయోగించాలి?\",\"పెద్ద VPS పూర్తి సమాధానంగా నిలిచిపోయినప్పుడు\":\"పెద్ద VPS ఒక్కటే పరిష్కారం కానప్పుడు\",\"కనిష్ట, ఆచరణాత్మక ఉత్పత్తి మరియు భారీ పనిభారం\":\"కనీస అవసరాలు, చిన్న ప్రొడక్షన్, భారీ పనిభారాలు\"},\"te/n8n-vps-security.html\":{\"గట్టిపడండి SSH\":\"SSH భద్రతను బలోపేతం చేయండి\",\"సర్వర్ దాడి ఉపరితలాన్ని తగ్గించండి\":\"సర్వర్‌పై దాడి జరిగే అవకాశాలను తగ్గించండి\",\"TLS ముగింపు\":\"TLS టెర్మినేషన్\",\"కనిష్ట ఓపెన్ పోర్ట్‌లు\":\"అవసరమైన పోర్టులనే తెరిచి ఉంచండి\",\"పర్యావరణ రహస్యాలు\":\"ఎన్విరాన్‌మెంట్‌లోని రహస్య విలువలు\",\"భద్రత అనేది ఒక ఆపరేటింగ్ ప్రక్రియ\":\"భద్రత నిరంతర నిర్వహణ ప్రక్రియ\"},\"te/n8n-queue-mode.html\":{\"కార్మికులు గణన మరియు ప్రతి కార్మికుని ఉద్యోగాల ద్వారా స్కేల్ చేస్తారు\":\"వర్కర్ల సంఖ్యతో పాటు ఒక్కో వర్కర్‌లో సమాంతర పనుల పరిమితి కూడా ముఖ్యం\",\"ఎప్పుడు రెగ్యులర్ మోడ్‌లో ఉండండి\":\"రెగ్యులర్ మోడ్‌లో ఎప్పుడు కొనసాగాలి?\",\"ఎప్పుడు క్యూ మోడ్‌ను పరిగణించండి\":\"Queue Modeను ఎప్పుడు పరిగణించాలి?\",\"ఎప్పుడు మొదట నిలువుగా స్కేల్ చేయండి\":\"ముందుగా VPS వనరులను ఎప్పుడు పెంచాలి?\",\"కార్మికుడు CPU & RAM\":\"వర్కర్ CPU, RAM\",\"PostgreSQL చూడండి\":\"PostgreSQL పనితీరును పర్యవేక్షించండి\",\"క్యూ సహాయం చేస్తుందో లేదో తెలుసుకోండి\":\"Queue Mode ఉపయోగపడుతోందో లేదో పరిశీలించండి\"}}")
PATTERN=re.compile(r'(<h[2-4]\b[^>]*>)([^<>]*)(</h[2-4]>)',re.I)
def main():
    for rel,patch in EDITS.items():
        p=ROOT/rel
        original=p.read_text(encoding="utf-8")
        hits=[]
        def rewrite(m):
            key=m.group(2).strip()
            if key not in patch:return m.group()
            hits.append(key)
            return m.group(1)+patch[key]+m.group(3)
        updated=PATTERN.sub(rewrite,original)
        if updated!=original:p.write_text(updated,encoding="utf-8")
        print("TELUGU_HEADING_REVIEW",rel,len(hits),"requested",len(patch),flush=True)
if __name__=="__main__":main()
